Aqui está a resolução completa, estruturada e detalhada para o problema **Energia**, seguindo a metodologia heurística de George Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA

- **Objetivo**: Dado um array de $N$ degraus com alturas $A_1, \dots, A_N$ e um parâmetro $K$, um par $(i, j)$ com $1 \le i < j \le N$ é dito *vulcônico* se $E(i, j) = |i - j| + |A_i - A_j| = K$. Degraus $D_1, D_2, \dots, D_Q$ desmoronam sucessivamente nos minutos $1, \dots, Q$. Jonas precisa reportar, para cada minuto $t \in [0, Q]$, quantos pares vulcônicos $(i, j)$ ainda existem de modo que nenhum degrau do intervalo $[i, j]$ tenha desmoronado até o minuto $t$.
- **Entrada**: 
  - $N, Q, K$ ($1 \le N \le 200\,000$, $0 \le Q < N$, $1 \le K \le 10^9$).
  - $A_1, \dots, A_N$ ($1 \le A_i \le 10^9$).
  - $Q$ inteiros $D_1, \dots, D_Q$ indicando os degraus que desmoronam.
- **Saída**: $Q + 1$ inteiros (um por linha), representando a quantidade de pares vulcônicos válidos em cada minuto de $0$ a $Q$.
- **Casos de Borda e Armadilhas**:
  - A contagem total de pares pode ultrapassar $2 \times 10^9$, sendo obrigatório o uso de inteiros de 64 bits (`long long`).
  - $Q = 0$ (nenhum desmoronamento).
  - Valores de $A_i$ e $K$ de até $10^9$, necessitando cuidado com overflow em somas.

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

1. **Propriedades da Energia**:
   Para $i < j$:
   $$E(i, j) = (j - i) + |A_i - A_j| = K$$
   Como $|A_i - A_j| \ge 0$, temos duas possibilidades mutuamente exclusivas:
   - **Caso A ($A_i \le A_j$)**: $(j + A_j) - (i + A_i) = K \iff P_j - P_i = K$, com a restrição $j - i \le K$.
   - **Caso B ($A_i > A_j$)**: $(j - A_j) - (i - A_i) = K \iff M_j - M_i = K$, com a restrição $j - i < K$.
   Onde $P_x = x + A_x$ e $M_x = x - A_x$.

2. **Tempo de Morte de um Par**:
   Seja $death\_time[x]$ o minuto em que o degrau $x$ desmorona ($1 \le death\_time[D_t] = t \le Q$). Degraus que nunca desmoronam recebem $death\_time = Q + 1$.
   Um par vulcônico $(i, j)$ morre no minuto:
   $$T(i, j) = \min_{k=i}^j death\_time[k]$$

3. **Árvore Cartesiana**:
   Construímos a Árvore Cartesiana (min-heap) sobre o array $death\_time$ (desempatando por índice).
   Para cada nó $u$, sua subárvore representa um intervalo $[L_u, R_u]$ onde $u$ é o elemento com menor tempo de desmoronamento. 
   Logo, todos os pares vulcônicos $(i, j)$ tais que $L_u \le i \le u \le j \le R_u$ (com $i < j$) morrem **exatamente** no minuto $death\_time[u]$!

4. **Técnica *Small-to-Large***:
   Para cada nó $u$, seja $C_u$ o número de pares vulcônicos $(i, j)$ com $L_u \le i \le u \le j \le R_u$.
   Comparamos o tamanho do lado esquerdo ($u - L_u$) com o lado direito ($R_u - u$):
   - Se a esquerda for menor ou igual, iteramos em $i \in [L_u, u]$ e contamos quantos $j$ válidos existem no lado direito via busca binária nos arrays ordenados de $P$ e $M$.
   - Se a direita for menor, iteramos em $j \in [u, R_u]$ e contamos quantos $i$ válidos existem no lado esquerdo via busca binária.
   Pelo princípio de dividir e conquistar / *small-to-large*, cada elemento é visitado no máximo $O(\log N)$ vezes. Cada consulta faz buscas binárias em $O(\log N)$, resultando em complexidade total de $O(N \log^2 N)$.

5. **Reconstrução da Resposta**:
   - $Ans[0] = \sum_{u=1}^N C_u$.
   - Para $t = 1, \dots, Q$: $Ans[t] = Ans[t - 1] - C_{D_t}$.

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

typedef struct {
    long long val;
    int idx;
} Element;

static int N, Q;
static long long K;
static long long A[MAXN];
static int D[MAXN];
static int death_time[MAXN];

static long long P_val[MAXN];
static long long M_val[MAXN];
static Element P_arr[MAXN];
static Element M_arr[MAXN];

static int left_child[MAXN];
static int right_child[MAXN];
static int L_bound[MAXN];
static int R_bound[MAXN];
static long long C[MAXN];

static inline long long min_ll(long long a, long long b) {
    return (a < b) ? a : b;
}

static inline long long max_ll(long long a, long long b) {
    return (a > b) ? a : b;
}

int cmp_elem(const void *a, const void *b) {
    const Element *ea = (const Element *)a;
    const Element *eb = (const Element *)b;
    if (ea->val != eb->val) {
        return (ea->val < eb->val) ? -1 : 1;
    }
    return (ea->idx < eb->idx) ? -1 : (ea->idx > eb->idx ? 1 : 0);
}

// Retorna quantos elementos em arr[1..N] têm val == target e low <= idx <= high
int count_in_range(Element *arr, int n, long long target, int low, int high) {
    if (low > high) return 0;

    int l = 1, r = n, first = n + 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid].val > target || (arr[mid].val == target && arr[mid].idx >= low)) {
            first = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }

    l = 1; r = n;
    int last = n + 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid].val > target || (arr[mid].val == target && arr[mid].idx > high)) {
            last = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }

    return last - first;
}

int main(void) {
    if (scanf("%d %d %lld", &N, &Q, &K) != 3) return 0;

    for (int i = 1; i <= N; i++) {
        scanf("%lld", &A[i]);
        death_time[i] = Q + 1;
    }

    for (int t = 1; t <= Q; t++) {
        scanf("%d", &D[t]);
        death_time[D[t]] = t;
    }

    for (int i = 1; i <= N; i++) {
        P_val[i] = (long long)i + A[i];
        M_val[i] = (long long)i - A[i];
        P_arr[i].val = P_val[i];
        P_arr[i].idx = i;
        M_arr[i].val = M_val[i];
        M_arr[i].idx = i;
    }

    qsort(P_arr + 1, N, sizeof(Element), cmp_elem);
    qsort(M_arr + 1, N, sizeof(Element), cmp_elem);

    // Construção linear da Árvore Cartesiana (min-heap em death_time, desempate por índice)
    static int stack[MAXN];
    int top = 0;
    for (int i = 1; i <= N; i++) {
        int last_popped = 0;
        while (top > 0) {
            int u = stack[top - 1];
            if (death_time[u] > death_time[i] || (death_time[u] == death_time[i] && u > i)) {
                last_popped = u;
                top--;
            } else {
                break;
            }
        }
        if (last_popped != 0) {
            left_child[i] = last_popped;
        }
        if (top > 0) {
            right_child[stack[top - 1]] = i;
        }
        stack[top++] = i;
    }

    int root = stack[0];

    // Obtenção da pós-ordem iterativamente para evitar estouro de pilha
    static int post_order[MAXN];
    int po_cnt = 0;
    top = 0;
    stack[top++] = root;
    while (top > 0) {
        int u = stack[--top];
        post_order[po_cnt++] = u;
        if (left_child[u]) stack[top++] = left_child[u];
        if (right_child[u]) stack[top++] = right_child[u];
    }

    // Processamento dos nós em pós-ordem
    for (int idx = po_cnt - 1; idx >= 0; idx--) {
        int u = post_order[idx];
        L_bound[u] = left_child[u] ? L_bound[left_child[u]] : u;
        R_bound[u] = right_child[u] ? R_bound[right_child[u]] : u;

        int sz_L = u - L_bound[u];
        int sz_R = R_bound[u] - u;
        long long cu = 0;

        if (sz_L <= sz_R) {
            for (int i = L_bound[u]; i <= u; i++) {
                int j_min = (i == u) ? u + 1 : u;

                // Caso A: P_j = P_i + K, j <= i + K
                int high_P = (int)min_ll(R_bound[u], (long long)i + K);
                if (j_min <= high_P) {
                    cu += count_in_range(P_arr, N, P_val[i] + K, j_min, high_P);
                }

                // Caso B: M_j = M_i + K, j < i + K
                int high_M = (int)min_ll(R_bound[u], (long long)i + K - 1);
                if (j_min <= high_M) {
                    cu += count_in_range(M_arr, N, M_val[i] + K, j_min, high_M);
                }
            }
        } else {
            for (int j = u; j <= R_bound[u]; j++) {
                int i_max = (j == u) ? u - 1 : u;

                // Caso A: P_i = P_j - K, i >= j - K
                int low_P = (int)max_ll(L_bound[u], (long long)j - K);
                if (low_P <= i_max) {
                    cu += count_in_range(P_arr, N, P_val[j] - K, low_P, i_max);
                }

                // Caso B: M_i = M_j - K, i > j - K <=> i >= j - K + 1
                int low_M = (int)max_ll(L_bound[u], (long long)j - K + 1);
                if (low_M <= i_max) {
                    cu += count_in_range(M_arr, N, M_val[j] - K, low_M, i_max);
                }
            }
        }
        C[u] = cu;
    }

    long long current_ans = 0;
    for (int i = 1; i <= N; i++) {
        current_ans += C[i];
    }

    // Minuto 0
    printf("%lld\n", current_ans);

    // Minutos 1 até Q
    for (int t = 1; t <= Q; t++) {
        current_ans -= C[D[t]];
        printf("%lld\n", current_ans);
    }

    return 0;
}
```

